WITH customer_aggregates AS ( SELECT c.c_customer_sk, c.c_customer_id, c.c_first_name, c.c_last_name, COUNT(ss.ss_ticket_number) AS purchase_count, SUM(ss.ss_net_paid) AS monetary_value, MAX(d.d_date) AS last_purchase_date, DATE_DIFF('day', MAX(d.d_date), CURRENT_DATE) AS recency_days FROM store_sales ss JOIN customer c ON ss.ss_customer_sk = c.c_customer_sk JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk GROUP BY c.c_customer_sk, c.c_customer_id, c.c_first_name, c.c_last_name ), latest_promo AS ( SELECT ss.ss_customer_sk, p.p_promo_name AS promo_name, ROW_NUMBER() OVER (PARTITION BY ss.ss_customer_sk ORDER BY d.d_date DESC) AS rn FROM store_sales ss JOIN promotion p ON ss.ss_promo_sk = p.p_promo_sk JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk ) SELECT ca.c_customer_id, ca.c_first_name, ca.c_last_name, ca.purchase_count, ca.monetary_value, ca.last_purchase_date, ca.recency_days, CASE WHEN ca.recency_days <= 30 AND ca.purchase_count >= 10 AND ca.monetary_value >= 1000 THEN 'Champion' WHEN ca.recency_days <= 60 AND ca.purchase_count >= 5 THEN 'Loyal' WHEN ca.recency_days > 180 THEN 'At Risk' ELSE 'New' END AS customer_segment, COALESCE(lp.promo_name, 'No Promo') AS latest_promo_name, ROW_NUMBER() OVER (ORDER BY ca.monetary_value DESC) AS monetary_rank, RANK() OVER (ORDER BY ca.recency_days ASC) AS recency_rank FROM customer_aggregates ca LEFT JOIN latest_promo lp ON ca.c_customer_sk = lp.ss_customer_sk AND lp.rn = 1 WHERE ca.recency_days <= 365 ORDER BY monetary_rank LIMIT 15
